// === Tab: mySketch ===
let particles = [];

function setup() {
createCanvas(windowWidth, windowHeight);
background(0);
}

function draw() {
background(0);

for (let i = 0; i < particles.length; i++) {
particles[i].update();
particles[i].show();
}

let p = new Particle((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
particles.push(p);
}

class Particle {
constructor(x, y) {
this.x = x;
this.y = y;
this.r = random(1, 5);
this.xspeed = random(-3, 3);
this.yspeed = random(-3, 3);
this.life = 255;
this.color = [255, random(100, 200), 0];
}

update() {
this.x += this.xspeed + noise(frameCount / 100) * 5; // Add a random component to the particle's movement using Perlin noise
this.y += this.yspeed + noise(frameCount / 100 + 1000) * -5;
this.life -= 1;
}

show() {
noStroke();
fill(this.color[0], this.color[1], this.color[2], this.life);
ellipse(this.x, this.y, this.r);
}
}

